package com.powercms.cms.widget.entity; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; @Entity @Table(name="widget_definition") public class WidgetDefinitionEntity { @Id private UUID id; @Column(name="site_id",nullable=false) private UUID siteId; @Column(nullable=false) private String code,name; @Column(name="controller_definition",nullable=false,columnDefinition="text") private String controllerDefinition; @Column(name="parameter_schema",nullable=false,columnDefinition="text") private String parameterSchema; @Column(nullable=false) private String status="DRAFT"; private String createdBy; @Column(nullable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; @PrePersist void c(){if(id==null)id=UUID.randomUUID();createdAt=updatedAt=Instant.now();}@PreUpdate void u(){updatedAt=Instant.now();} public UUID getId(){return id;} public UUID getSiteId(){return siteId;} public void setSiteId(UUID x){siteId=x;} public String getCode(){return code;} public void setCode(String x){code=x;} public String getName(){return name;} public void setName(String x){name=x;} public String getControllerDefinition(){return controllerDefinition;} public void setControllerDefinition(String x){controllerDefinition=x;} public String getParameterSchema(){return parameterSchema;} public void setParameterSchema(String x){parameterSchema=x;} public String getStatus(){return status;} public void setStatus(String x){status=x;} }
